//! Success and failure responses and their one-line JSON encoding.

use std::io::{self, Write};

use serde::Serialize;

use crate::error::Error;
use crate::types::Instant;

/// The result members of a successful command.
#[derive(Debug, Serialize)]
#[serde(untagged)]
pub enum Reply {
    Empty {},
    Tick {
        #[serde(rename = "Now")]
        now: Instant,
    },
}

#[derive(Serialize)]
struct Success<'a> {
    ok: bool,
    #[serde(flatten)]
    reply: &'a Reply,
}

#[derive(Serialize)]
struct Failure<'a> {
    ok: bool,
    error: &'a Error,
}

/// Writes one response line, including the final newline.
pub fn write_response(result: &Result<Reply, Error>, out: &mut impl Write) -> io::Result<()> {
    match result {
        Ok(reply) => serde_json::to_writer(&mut *out, &Success { ok: true, reply })?,
        Err(error) => serde_json::to_writer(&mut *out, &Failure { ok: false, error })?,
    }
    out.write_all(b"\n")
}
EOF
cat > src/request.rs <<'EOF'
//! Turns one input line into a validated request.
//!
//! Checks run in the order of the specification: request shape, required
//! parameters, then parameter values.

use serde_json::{Map, Value};

use crate::error::{Error, ErrorCode};
use crate::types::{Seconds, TICK_RANGE};

/// A command name the protocol knows.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Command {
    Tick,
}

impl Command {
    fn from_name(name: &str) -> Option<Self> {
        match name {
            "Tick" => Some(Self::Tick),
            _ => None,
        }
    }
}

/// A validated command with its parameters.
#[derive(Debug, PartialEq, Eq)]
pub enum Request {
    Tick { seconds: Seconds },
}

/// A line that is a JSON object with a known `Command`, parameters not yet checked.
pub struct Document {
    command: Command,
    members: Map<String, Value>,
}

impl Document {
    pub fn parse(line: &[u8]) -> Result<Self, Error> {
        let value: Value = serde_json::from_slice(line).map_err(|e| {
            Error::new(
                ErrorCode::InvalidRequest,
                format!("line is not valid JSON: {e}"),
            )
        })?;
        let Value::Object(members) = value else {
            return Err(Error::new(
                ErrorCode::InvalidRequest,
                "line is not a JSON object",
            ));
        };
        let Some(Value::String(name)) = members.get("Command") else {
            return Err(Error::new(
                ErrorCode::InvalidRequest,
                "member Command is missing or not a string",
            ));
        };
        let command = Command::from_name(name).ok_or_else(|| {
            Error::new(ErrorCode::InvalidRequest, format!("unknown command {name}"))
        })?;
        Ok(Self { command, members })
    }

    pub fn request(&self) -> Result<Request, Error> {
        let params = Params(&self.members);
        match self.command {
            Command::Tick => {
                params.require(&["Seconds"])?;
                let seconds = params.required_integer("Seconds", TICK_RANGE)?;
                Ok(Request::Tick {
                    seconds: Seconds::new(seconds),
                })
            }
        }
    }
}

/// Read access to the parameters of one command; `null` counts as absent.
#[derive(Clone, Copy)]
struct Params<'a>(&'a Map<String, Value>);

impl Params<'_> {
    fn get(self, name: &str) -> Option<&Value> {
        self.0.get(name).filter(|value| !value.is_null())
    }

    fn require(self, names: &[&str]) -> Result<(), Error> {
        match names.iter().find(|name| self.get(name).is_none()) {
            Some(name) => Err(Error::missing(name)),
            None => Ok(()),
        }
    }

    fn required_integer(
        self,
        name: &str,
        range: std::ops::RangeInclusive<u32>,
    ) -> Result<u32, Error> {
        let Some(value) = self.get(name) else {
            return Err(Error::missing(name));
        };
        // `as_i64` rejects fractions and exponents because numbers keep their source text.
        let number = value
            .as_number()
            .and_then(|n| n.as_i64())
            .ok_or_else(|| Error::invalid(name, "must be an integer"))?;
        u32::try_from(number)
            .ok()
            .filter(|n| range.contains(n))
            .ok_or_else(|| {
                Error::invalid(
                    name,
                    &format!("must be between {} and {}", range.start(), range.end()),
                )
            })
    }
}
