cat > src/broker.rs <<'EOF'
//! The state of the service and the execution of commands against it.

use crate::error::Error;
use crate::request::{Document, Request};
use crate::response::Reply;
use crate::types::Instant;

/// All service state: the virtual clock and, later, the queues.
pub struct Broker {
    now: Instant,
}

impl Broker {
    pub fn new() -> Self {
        Self {
            now: Instant::START,
        }
    }

    /// Runs the command on one input line, which has no trailing newline.
    pub fn handle_line(&mut self, line: &[u8]) -> Result<Reply, Error> {
        let document = Document::parse(line)?;
        match document.request()? {
            Request::Tick { seconds } => {
                self.now = self.now.plus(seconds);
                Ok(Reply::Tick { now: self.now })
            }
        }
    }
}

impl Default for Broker {
    fn default() -> Self {
        Self::new()
    }
}
EOF
cat > src/lib.rs <<'EOF'
//! miniq: a small in-memory message queue driven by one JSON command per line.

mod broker;
mod error;
mod request;
mod response;
mod types;

use std::io::{self, BufRead, Write};

pub use broker::Broker;
pub use error::{Error, ErrorCode};
pub use response::{Reply, write_response};

/// Answers every line of `input` with one response line on `output`, flushing after each.
pub fn run(mut input: impl BufRead, mut output: impl Write) -> io::Result<()> {
    let mut broker = Broker::new();
    let mut line = Vec::new();
    let mut response = Vec::new();
    loop {
        line.clear();
        if input.read_until(b'\n', &mut line)? == 0 {
            return Ok(());
        }
        if line.last() == Some(&b'\n') {
            line.pop();
        }
        response.clear();
        write_response(&broker.handle_line(&line), &mut response)?;
        output.write_all(&response)?;
        output.flush()?;
    }
}
EOF
