    pub fn parse(text: &str) -> Result<Self, Error> {
        if (1..=1024).contains(&text.len()) {
            Ok(Self(text.to_owned()))
        } else {
            Err(Error::invalid("Body", "must be 1 to 1024 bytes long"))
        }
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

