#[derive(Debug, Clone, PartialEq, Eq)]
pub struct DeduplicationId(String);

impl DeduplicationId {
    pub fn parse(text: &str) -> Result<Self, Error> {
        parse_token("DeduplicationId", text).map(Self)
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }

    pub fn into_string(self) -> String {
        self.0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn queue_names_follow_the_naming_rules() {
        let long_plain = "a".repeat(80);
        let long_fifo = format!("{}.fifo", "a".repeat(75));
        let too_long_plain = "a".repeat(81);
        let too_long_fifo = format!("{}.fifo", "a".repeat(76));
        let accepted = [
            "a",
            "A-z_9",
            "a.fifo",
            "fifo",
            long_plain.as_str(),
            long_fifo.as_str(),
        ];
        let rejected = [
            "",
            ".fifo",
            "a.fifo.fifo",
            "a b",
            "a.",
            "\u{e9}",
            "a.FIFO",
            too_long_plain.as_str(),
            too_long_fifo.as_str(),
        ];
        for name in accepted {
            assert!(QueueName::parse(name).is_ok(), "{name:?}");
        }
        for name in rejected {
            let error = QueueName::parse(name).expect_err(name);
            assert_eq!(error.code(), ErrorCode::QueueNameInvalid, "{name:?}");
        }
    }

    #[test]
    fn only_the_suffix_makes_a_queue_fifo() {
        assert!(QueueName::parse("a.fifo").unwrap().is_fifo());
        assert!(!QueueName::parse("fifo").unwrap().is_fifo());
    }
}
