    ]);
    assert_eq!(responses[2], json!({"ok": true, "MessageId": "m-1"}));
    assert_eq!(error_code(&responses[3]), "InvalidParameterValue");
    assert_eq!(responses[4], json!({"ok": true, "MessageId": "m-2"}));
}

#[test]
fn send_validates_parameters_in_order() {
    let long_body = "x".repeat(1025);
    let long_bytes = "\u{e9}".repeat(513);
    let big_ok = "\u{e9}".repeat(512);
    let too_long_body = format!(r#"{{"Command":"SendMessage","QueueName":"q","Body":"{long_body}"}}"#);
    let too_long_bytes = format!(r#"{{"Command":"SendMessage","QueueName":"q","Body":"{long_bytes}"}}"#);
    let max_bytes = format!(r#"{{"Command":"SendMessage","QueueName":"q","Body":"{big_ok}"}}"#);
    let cases = [
        (r#"{"Command":"SendMessage","Body":5}"#, "MissingParameter"),
        (r#"{"Command":"SendMessage","QueueName":"q"}"#, "MissingParameter"),
        (r#"{"Command":"SendMessage","QueueName":"nope","Body":5}"#, "InvalidParameterValue"),
        (r#"{"Command":"SendMessage","QueueName":"nope","Body":"a"}"#, "QueueDoesNotExist"),
        (r#"{"Command":"SendMessage","QueueName":"q","Body":"a","DelaySeconds":901}"#, "InvalidParameterValue"),
        (r#"{"Command":"SendMessage","QueueName":"q","Body":"a","GroupId":"bad id"}"#, "InvalidParameterValue"),
        (r#"{"Command":"SendMessage","QueueName":"q","Body":"a","DeduplicationId":""}"#, "InvalidParameterValue"),
        (r#"{"Command":"SendMessage","QueueName":"q","Body":"a","GroupId":"g"}"#, "UnsupportedOperation"),
        (r#"{"Command":"SendMessage","QueueName":"q","Body":"a","DeduplicationId":"d"}"#, "UnsupportedOperation"),
        (too_long_body.as_str(), "InvalidParameterValue"),
        (too_long_bytes.as_str(), "InvalidParameterValue"),
    ];
    for (line, code) in cases {
        let responses = run(&[STANDARD, line]);
        assert_eq!(error_code(&responses[1]), code, "{line}");
    }
    assert_eq!(run(&[STANDARD, &max_bytes])[1], json!({"ok": true, "MessageId": "m-1"}));
}

#[test]
fn fifo_send_rules_and_sequence_numbers() {
    let cases = [
        (r#"{"Command":"SendMessage","QueueName":"f.fifo","Body":"a","DelaySeconds":0,"GroupId":"g","DeduplicationId":"d"}"#, "UnsupportedOperation"),
        (r#"{"Command":"SendMessage","QueueName":"f.fifo","Body":"a","DeduplicationId":"d"}"#, "MissingParameter"),
        (r#"{"Command":"SendMessage","QueueName":"f.fifo","Body":"a","GroupId":"g"}"#, "MissingParameter"),
    ];
    for (line, code) in cases {
        assert_eq!(error_code(&run(&[FIFO, line])[1]), code, "{line}");
    }
    let responses = run(&[
        FIFO,
