        r#"{"Command":"SendMessage","QueueName":"f.fifo","Body":"a","GroupId":"h","DeduplicationId":"2"}"#,
    ]);
    assert_eq!(responses[1], json!({"ok": true, "MessageId": "m-1", "SequenceNumber": 1}));
    assert_eq!(responses[2], json!({"ok": true, "MessageId": "m-2", "SequenceNumber": 2}));
}

