fn find_queue<'a>(
    queues: &'a mut BTreeMap<QueueName, Queue>,
    now: Instant,
    name: &str,
) -> Result<&'a mut Queue, Error> {
    let queue = queues.get_mut(name).ok_or_else(|| {
        Error::new(
            ErrorCode::QueueDoesNotExist,
            format!("queue {name:?} does not exist"),
        )
    })?;
    queue.expire(now);
